# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GENEL DÖRTGEN VE YAMUK ÖZELLİKLERİ</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">DİK KÖŞEGENLİ DÖRTGEN (AC ⊥ BD)</text>\n  <polygon points="70,150 160,80 260,145 155,195" fill="#ffffff" stroke="#1d4ed8" stroke-width="2"/>\n  <line x1="70" y1="150" x2="260" y2="145" stroke="#dc2626" stroke-width="1.5" stroke-dasharray="4,2"/>\n  <line x1="160" y1="80" x2="155" y2="195" stroke="#dc2626" stroke-width="1.5" stroke-dasharray="4,2"/>\n  <text x="105" y="108" font-size="10" font-weight="bold" fill="#1e40af">a</text>\n  <text x="218" y="106" font-size="10" font-weight="bold" fill="#1e40af">b</text>\n  <text x="215" y="182" font-size="10" font-weight="bold" fill="#1e40af">c</text>\n  <text x="102" y="184" font-size="10" font-weight="bold" fill="#1e40af">d</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">a² + c² = b² + d²  |  Alan = (|AC| · |BD|) / 2</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">YAMUKTA ORTA TABAN VE ALAN ([AB] // [DC])</text>\n  <polygon points="400,175 640,175 590,95 450,95" fill="#ffffff" stroke="#b45309" stroke-width="2"/>\n  <line x1="425" y1="135" x2="615" y2="135" stroke="#16a34a" stroke-width="2" stroke-dasharray="5,3"/>\n  <line x1="450" y1="95" x2="450" y2="175" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="520" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">Üst Taban (c)</text>\n  <text x="520" y="130" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Orta Taban: e = (a + c) / 2</text>\n  <text x="520" y="190" text-anchor="middle" font-size="10" font-weight="bold" fill="#92400e">Alt Taban (a)</text>\n  <text x="462" y="158" font-size="10" font-weight="bold" fill="#dc2626">h</text>\n  <text x="520" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Alan = ((a + c) / 2) · h = e · h</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">PARALELKENAR VE EŞKENAR DÖRTGEN KARŞILAŞTIRMASI</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">PARALELKENAR ÖZELLİKLERİ</text>\n  <polygon points="55,170 255,170 295,95 95,95" fill="#ffffff" stroke="#4338ca" stroke-width="2"/>\n  <line x1="55" y1="170" x2="295" y2="95" stroke="#6366f1" stroke-width="1.5" stroke-dasharray="4,2"/>\n  <line x1="95" y1="95" x2="255" y2="170" stroke="#6366f1" stroke-width="1.5" stroke-dasharray="4,2"/>\n  <text x="175" y="118" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">S</text>\n  <text x="175" y="156" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">S</text>\n  <text x="125" y="136" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">S</text>\n  <text x="225" y="136" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">S</text>\n  <text x="180" y="192" text-anchor="middle" font-size="9.5" fill="#334155">• Karşılıklı kenarlar ve açılar eşittir; köşegenler ortalanır.</text>\n  <text x="180" y="208" text-anchor="middle" font-size="10" font-weight="bold" fill="#3730a3">Alan = a · h_a = b · h_b = 4S (Simetri ekseni: 0)</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">EŞKENAR DÖRTGEN (4 KENAR EŞİT)</text>\n  <polygon points="520,82 610,130 520,178 430,130" fill="#ffffff" stroke="#15803d" stroke-width="2"/>\n  <line x1="430" y1="130" x2="610" y2="130" stroke="#dc2626" stroke-width="1.5"/>\n  <line x1="520" y1="82" x2="520" y2="178" stroke="#dc2626" stroke-width="1.5"/>\n  <rect x="520" y="122" width="8" height="8" fill="none" stroke="#dc2626" stroke-width="1.2"/>\n  <text x="520" y="194" text-anchor="middle" font-size="9.5" fill="#334155">• Köşegenler dik ortalanır ve iç açıortaydır.</text>\n  <text x="520" y="210" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Alan = a · h = (|AC| · |BD|) / 2 (Simetri ekseni: 2)</text>\n</svg>', '<svg viewBox="0 0 700 230" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="230" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DİKDÖRTGEN, KARE VE DELTOİDİN TEMEL ÖZELLİKLERİ</text>\n  <rect x="20" y="48" width="210" height="162" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. DİKDÖRTGEN</text>\n  <text x="125" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Tüm açılar 90°, karşıt kenarlar eşit.</text>\n  <text x="125" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Köşegenler eşit ve ortalanır:</text>\n  <text x="125" y="130" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1d4ed8">|AC| = |BD| = kök(a² + b²)</text>\n  <text x="125" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Alan = a · b | Çevre = 2(a + b)</text>\n  <text x="125" y="170" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e40af">• Simetri Ekseni: 2 (Kenar ortalar)</text>\n\n  <rect x="245" y="48" width="210" height="162" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">2. KARE (Düzgün Dörtgen)</text>\n  <text x="350" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• 4 kenar eşit, tüm açılar 90°.</text>\n  <text x="350" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Köşegenler eşit, dik ortalanır</text>\n  <text x="350" y="130" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#b45309">ve 45°-45° açıortaydır: e = a·kök(2)</text>\n  <text x="350" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Alan = a² = e² / 2 | Çevre = 4a</text>\n  <text x="350" y="170" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#92400e">• Simetri Ekseni: 4 (2 köşegen+2 orta)</text>\n\n  <rect x="470" y="48" width="210" height="162" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="575" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">3. DELTOİD</text>\n  <text x="575" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Tabanları ortak iki ikizkenar üçgen.</text>\n  <text x="575" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Köşegenler dik kesişir (AC ⊥ BD).</text>\n  <text x="575" y="132" text-anchor="middle" font-size="9.5" fill="#334155">• Esas köşegen açıortaydır ve</text>\n  <text x="575" y="148" text-anchor="middle" font-size="9.5" fill="#334155">diğer köşegeni iki eş parçaya böler.</text>\n  <text x="575" y="170" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#6b21a8">• Alan = (|AC|·|BD|)/2 | Simetri: 1</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
